extern IGrim2D_cpp *grim_interface_ptr;

struct ui_cursor_vec2_t {
    union {
        struct { float x, y; };
        float v[2];
    };

    ui_cursor_vec2_t() {}

    ui_cursor_vec2_t(float x_value, float y_value)
    {
        x = x_value;
        y = y_value;
    }

    ui_cursor_vec2_t operator-(const ui_cursor_vec2_t &other)
    {
        return ui_cursor_vec2_t(x - other.x, y - other.y);
    }

    ui_cursor_vec2_t &operator-=(const ui_cursor_vec2_t &other)
    {
        x -= other.x;
        y -= other.y;
        return *this;
    }
};

ui_cursor_vec2_t cursor_position =
    *(ui_cursor_vec2_t *)&ui_mouse_x
    - ui_cursor_vec2_t(2.0f, 2.0f);
grim_interface_ptr->grim_draw_quad(
    cursor_position.x, cursor_position.y, 32.0f, 32.0f);

ui_cursor_vec2_t cursor_position =
    ui_cursor_vec2_t(ui_mouse_x, ui_mouse_y)
    - ui_cursor_vec2_t(2.0f, 2.0f);
grim_interface_ptr->grim_draw_quad(
    cursor_position.x, cursor_position.y, 32.0f, 32.0f);

ui_cursor_vec2_t cursor_position =
    *(ui_cursor_vec2_t *)&ui_mouse_x;
cursor_position -= ui_cursor_vec2_t(2.0f, 2.0f);
grim_interface_ptr->grim_draw_quad(
    cursor_position.x, cursor_position.y, 32.0f, 32.0f);

ui_cursor_vec2_t cursor_position(ui_mouse_x, ui_mouse_y);
cursor_position -= ui_cursor_vec2_t(2.0f, 2.0f);
grim_interface_ptr->grim_draw_quad(
    cursor_position.x, cursor_position.y, 32.0f, 32.0f);
